import manifest from "@/content/recovered-site/business-operations/manifest.json";

/**
 * Recovered Business Operations pages: verbatim historical content with provenance.
 * Generated by scripts/recovery/recover_business_operations.py (do not edit the JSON by hand).
 */
export type RecoveredGeneration = "static-20260729" | "static-20260701" | "fork-20260819";

export type RecoveredPage = {
  route: string;
  generation: RecoveredGeneration;
  source: { commit: string; path: string; label: string };
  merges: Array<{ commit: string; path: string }>;
  title: string;
  description: string;
  bodyClass: string;
  mainClass: string;
  mainId: string;
  html: string;
  inlineScripts: string[];
  widgetScripts: string[];
  archive: boolean;
};

type ManifestEntry = { key: string; title: string; description: string; generation: RecoveredGeneration; archive: boolean };

const ENTRIES = manifest as Record<string, ManifestEntry>;

export function recoveredRoutes(): string[] {
  return Object.keys(ENTRIES);
}

export function recoveredEntry(route: string): ManifestEntry | null {
  return ENTRIES[route] ?? null;
}

export async function loadRecoveredPage(route: string): Promise<RecoveredPage | null> {
  const entry = ENTRIES[route];
  if (!entry) return null;
  const mod = await import(`@/content/recovered-site/business-operations/${entry.key}.json`);
  return (mod.default ?? mod) as RecoveredPage;
}
